package com.vinhho.onthi10ai.data.solver

import com.vinhho.onthi10ai.data.solver.OfflineQuizBank.RawQuestion

internal object OfflineQuizBankHistory {

    fun buildForGrade(grade: Int): List<RawQuestion> = when (grade) {
        in 1..5 -> primaryQuestions(grade)
        in 6..9 -> secondaryQuestions(grade)
        else -> highSchoolQuestions(grade)
    }

    private fun primaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Lịch sử Lớp $g]"
        return listOf(
            RawQuestion("$tag Nhà nước đầu tiên của dân tộc Việt Nam là nhà nước nào?", listOf("Văn Lang", "Âu Lạc", "Đại Cồ Việt", "Đại Việt"), 0, "Các vua Hùng dựng nước Văn Lang bên lưu vực sông Hồng."),
            RawQuestion("$tag Người anh hùng nhỏ tuổi bóp nát quả cam và giương cao lá cờ 'Phá cường địch, báo hoàng ân' là ai?", listOf("Trần Quốc Toản", "Kim Đồng", "Lý Tự Trọng", "Võ Thị Sáu"), 0, "Trần Quốc Toản là thiếu niên anh hùng trong kháng chiến chống quân Nguyên thời Trần."),
            RawQuestion("$tag Hai Bà Trưng phất cờ khởi nghĩa chống quân xâm lược nào vào năm 40?", listOf("Quân Đông Hán", "Quân Tống", "Quân Minh", "Quân Thanh"), 0, "Trưng Trắc và Trưng Nhị lãnh đạo nhân dân đánh đuổi thái thú Tô Định nhà Đông Hán."),
            RawQuestion("$tag Chiến thắng Bạch Đằng năm 938 gắn với tên tuổi vị anh hùng nào?", listOf("Ngô Quyền", "Đinh Bộ Lĩnh", "Lê Hoàn", "Lý Thái Tổ"), 0, "Ngô Quyền dùng trận địa cọc gỗ đánh tan quân Nam Hán năm 938."),
            RawQuestion("$tag Ai là người dẹp loạn 12 sứ quân, thống nhất đất nước và đặt tên nước là Đại Cồ Việt?", listOf("Đinh Bộ Lĩnh", "Ngô Quyền", "Lê Lợi", "Quang Trung"), 0, "Năm 968, Đinh Bộ Lĩnh lên ngôi Hoàng đế (Đinh Tiên Hoàng), đóng đô ở Hoa Lư."),
            RawQuestion("$tag Năm 1010, vua Lý Thái Tổ dời đô từ Hoa Lư về đâu?", listOf("Thành Đại La (đổi tên thành Thăng Long)", "Phú Xuân (Huế)", "Cổ Loa", "Lam Kinh"), 0, "Vua Lý Thái Tổ viết Chiếu dời đô và đặt tên kinh đô mới là Thăng Long."),
            RawQuestion("$tag Ai được coi là tác giả bài thơ thần 'Nam quốc sơn hà'?", listOf("Lý Thường Kiệt", "Trần Hưng Đạo", "Nguyễn Trãi", "Lê Thánh Tông"), 0, "Bài thơ khích lệ tinh thần quân dân nhà Lý chống quân Tống trên sông Như Nguyệt."),
            RawQuestion("$tag Hội nghị Diên Hồng dưới thời Trần có ý nghĩa gì?", listOf("Thể hiện ý chí đoàn kết quyết tâm chống giặc Nguyên - Mông của toàn dân", "Ký kết hòa ước nhượng đất", "Bầu chọn trạng nguyên", "Chia lại ruộng đất"), 0, "Các bô lão cả nước đồng thanh hô vang 'Đánh!' trước nguy cơ ngoại xâm."),
            RawQuestion("$tag Ba lần kháng chiến chống quân xâm lược Mông - Nguyên diễn ra dưới triều đại nào?", listOf("Nhà Trần", "Nhà Lý", "Nhà Hồ", "Nhà Nguyễn"), 0, "Nhà Trần ba lần đánh thắng quân Mông - Nguyên vào các năm 1258, 1285 và 1288."),
