            RawQuestion("$tag Vị nữ tướng cưỡi voi ra trận với câu nói nổi tiếng 'Tôi muốn cưỡi cơn gió mạnh, đạp luồng sóng dữ...' là ai?", listOf("Bà Triệu (Triệu Thị Trinh)", "Bùi Thị Xuân", "Nguyễn Thị Minh Khai", "Trưng Nhị"), 0, "Bà Triệu lãnh đạo khởi nghĩa chống quân Ngô năm 248."),
            RawQuestion("$tag Sự kiện ngày 19/8/1945 ở Hà Nội gắn với thắng lợi nào?", listOf("Tổng khởi nghĩa Cách mạng tháng Tám giành chính quyền ở Hà Nội", "Ngày Toàn quốc kháng chiến", "Thành lập Đội Nhi đồng Cứu quốc", "Bác Hồ về Pác Bó"), 0, "Ngày 19/8 trở thành ngày kỉ niệm Cách mạng tháng Tám thành công."),
            RawQuestion("$tag Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập ngày 22/12/1944 do ai làm đội trưởng chỉ huy trực tiếp?", listOf("Võ Nguyên Giáp", "Hoàng Văn Thụ", "Phạm Văn Đồng", "Nguyễn Văn Cừ"), 0, "Đại tướng Võ Nguyên Giáp là người anh cả của Quân đội nhân dân Việt Nam."),
            RawQuestion("$tag Chiến thắng 'Điện Biên Phủ trên không' cuối năm 1972 diễn ra chủ yếu ở đâu?", listOf("Hà Nội và Hải Phòng", "Huế và Đà Nẵng", "Sài Gòn và Cần Thơ", "Cao Bằng và Lạng Sơn"), 0, "Quân dân miền Bắc bắn rơi nhiều máy bay B-52 của Mỹ trong 12 ngày đêm tháng 12/1972."),
