            RawQuestion("$tag Thánh Gióng là nhân vật truyền thuyết tượng trưng cho điều gì?", listOf("Sức mạnh đoàn kết chống giặc ngoại xâm của dân tộc", "Nghề trồng lúa nước", "Tình yêu thiên nhiên", "Nghề đúc đồng"), 0, "Thánh Gióng vươn vai thành tráng sĩ đánh đuổi giặc Ân."),
            RawQuestion("$tag Lễ hội Đền Hùng hiện nay được tổ chức tại tỉnh nào?", listOf("Phú Thọ", "Ninh Bình", "Bắc Ninh", "Thanh Hóa"), 0, "Khu di tích lịch sử Đền Hùng nằm trên núi Nghĩa Lĩnh, tỉnh Phú Thọ."),
