            RawQuestion("$tag Quốc tử giám - trường đại học đầu tiên của nước ta được xây dựng dưới triều đại nào?", listOf("Nhà Lý", "Nhà Đinh", "Nhà Ngô", "Nhà Nguyễn"), 0, "Vua Lý Nhân Tông cho lập Quốc Tử Giám năm 1076."),
            RawQuestion("$tag Bộ luật thành văn đầu tiên của nước ta (Hình thư) được ban hành dưới triều nào?", listOf("Nhà Lý", "Nhà Tiền Lê", "Nhà Hồ", "Nhà Mạc"), 0, "Vua Lý Thái Tông ban hành bộ Hình thư năm 1042."),
            RawQuestion("$tag Hội nghị thành lập Đảng Cộng sản Việt Nam đầu năm 1930 do ai chủ trì?", listOf("Nguyễn Ái Quốc", "Trần Phú", "Lê Hồng Phong", "Hà Huy Tập"), 0, "Nguyễn Ái Quốc chủ trì Hội nghị hợp nhất các tổ chức cộng sản đầu năm 1930."),
            RawQuestion("$tag Chiến dịch Biên giới Thu - Đông năm 1950 có ý nghĩa gì?", listOf("Khai thông biên giới Việt - Trung, mở rộng căn cứ địa Việt Bắc", "Giải phóng miền Nam", "Thành lập nước Đại Việt", "Ký Hiệp định Pa-ri"), 0, "Lần đầu tiên quân đội ta chủ động mở chiến dịch tiến công quy mô lớn."),
