    private fun secondaryQuestions(g: Int): List<RawQuestion> {
        val tag = "[Lịch sử Lớp $g]"
        return listOf(
            RawQuestion("$tag Văn minh Ai Cập cổ đại hình thành trên lưu vực dòng sông nào?", listOf("Sông Nin (Nile)", "Sông Ấn", "Sông Hoàng Hà", "Sông Ơ-phrát"), 0, "Ai Cập cổ đại phát triển rực rỡ nhờ phù sa màu mỡ của sông Nin."),
            RawQuestion("$tag Chữ viết cổ của người Lưỡng Hà là loại chữ gì?", listOf("Chữ hình nêm (chữ tiết hình)", "Chữ tượng hình trên giấy cói", "Chữ La-tinh", "Chữ Quốc ngữ"), 0, "Người Lưỡng Hà khắc các nét hình nêm lên bảng đất sét ướt."),
            RawQuestion("$tag Cuộc Cách mạng tư sản Anh thế kỷ XVII diễn ra dưới hình thức nào?", listOf("Nội chiến giữa Vua và Quốc hội", "Chiến tranh giành độc lập thuộc địa", "Cách mạng vô sản", "Cải cách từ trên xuống"), 0, "Kết thúc bằng chế độ quân chủ lập hiến tại Anh."),
            RawQuestion("$tag Tuyên ngôn Độc lập của hợp chúng quốc Hoa Kỳ ra đời vào năm nào?", listOf("1776", "1789", "1640", "1848"), 0, "Ngày 4/7/1776, 13 bang thuộc địa Bắc Mỹ tuyên bố độc lập."),
            RawQuestion("$tag Sự kiện nào mở đầu cho Cách mạng tư sản Pháp năm 1789?", listOf("Quần chúng nhân dân tấn công pháo đài nhà ngục Ba-xti (14/7/1789)", "Hội nghị Véc-xai", "Chiến tranh Bảy năm", "Nữ hoàng lên ngôi"), 0, "Ngày 14/7 trở thành Quốc khánh nước Cộng hòa Pháp."),
            RawQuestion("$tag Cuộc Cách mạng công nghiệp lần thứ nhất (cuối thế kỷ XVIII) bắt đầu ở quốc gia nào?", listOf("Nước Anh", "Nước Pháp", "Nước Đức", "Nước Mỹ"), 0, "Phát minh máy hơi nước của Giêm Oát thúc đẩy công nghiệp hóa mạnh mẽ tại Anh."),
